import{supabase as d}from"./supabase-DUkCiNAm.js";/* empty css              */document.getElementById("login-form").addEventListener("submit",async t=>{t.preventDefault();let o=document.getElementById("email").value.trim();o.includes("@")||(o+="@automatizap.com");const i=document.getElementById("password").value,n=document.getElementById("login-error"),e=document.querySelector(".login-btn");e.textContent="Entrando...",e.disabled=!0,n.style.display="none";const{data:m,error:r}=await d.auth.signInWithPassword({email:o,password:i});if(r){e.textContent="Entrar",e.disabled=!1,n.textContent="Erro do Banco: "+r.message,n.style.display="block";const s=document.querySelector(".login-form-container");s.style.transform="translateX(-10px)",setTimeout(()=>s.style.transform="translateX(10px)",100),setTimeout(()=>s.style.transform="translateX(-10px)",200),setTimeout(()=>s.style.transform="translateX(0)",300)}else window.location.href="index.html"});const l=document.getElementById("togglePassword"),a=document.getElementById("password");l&&a&&l.addEventListener("click",function(){const t=a.getAttribute("type")==="password"?"text":"password";a.setAttribute("type",t),t==="password"?(this.classList.remove("ph-eye-slash"),this.classList.add("ph-eye")):(this.classList.remove("ph-eye"),this.classList.add("ph-eye-slash"))});
